run:
if ! test -n "$DSH_PREVIOUS_TAG"; then echo "DSH_PREVIOUS_TAG must name the previous adopted release tag" >&2; exit 2; fi
case "$DSH_REBRAND_EPOCH_MODE" in
  current-script-hash) exec pnpm run import:dsh-release -- --checkout "{checkout}" --previous-tag "$DSH_PREVIOUS_TAG" --previous-commit "{base_ref}" --tag "{target}" --current-rebrand-epoch --apply ;;
  recorded-chain) exec pnpm run import:dsh-release -- --checkout "{checkout}" --previous-tag "$DSH_PREVIOUS_TAG" --previous-commit "{base_ref}" --tag "{target}" --recorded-rebrand-epoch --apply ;;
  *) echo "DSH_REBRAND_EPOCH_MODE must be current-script-hash or recorded-chain" >&2; exit 2 ;;
esac

if ! test -n "$DSH_PREVIOUS_TAG"; then echo "DSH_PREVIOUS_TAG must name the previous adopted release tag" >&2; exit 2; fi
case "$DSH_REBRAND_EPOCH_MODE" in
  current-script-hash) exec pnpm run import:dsh-release -- --checkout "{checkout}" --previous-tag "$DSH_PREVIOUS_TAG" --previous-commit "{base_ref}" --tag "{target}" --current-rebrand-epoch --check ;;
  recorded-chain) exec pnpm run import:dsh-release -- --checkout "{checkout}" --previous-tag "$DSH_PREVIOUS_TAG" --previous-commit "{base_ref}" --tag "{target}" --recorded-rebrand-epoch --check ;;
  *) echo "DSH_REBRAND_EPOCH_MODE must be current-script-hash or recorded-chain" >&2; exit 2 ;;
esac
